CREATE TABLE IF NOT EXISTS risks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), seq BIGSERIAL UNIQUE NOT NULL, incident_date DATE NOT NULL, incident_time TIME, reporter TEXT NOT NULL DEFAULT '', unit TEXT NOT NULL, location TEXT NOT NULL DEFAULT '', risk_group TEXT NOT NULL CHECK (risk_group IN ('clinical','general')), safety_category TEXT NOT NULL DEFAULT '', risk_code TEXT NOT NULL DEFAULT '', event_title TEXT NOT NULL, event_detail TEXT NOT NULL, immediate_action TEXT NOT NULL DEFAULT '', severity TEXT NOT NULL, is_priority BOOLEAN NOT NULL DEFAULT FALSE, status TEXT NOT NULL DEFAULT 'reported' CHECK (status IN ('reported','reviewing','monitoring','closed')), reviewer TEXT NOT NULL DEFAULT '', review_date DATE, root_cause TEXT NOT NULL DEFAULT '', contributing_factors TEXT NOT NULL DEFAULT '', corrective_action TEXT NOT NULL DEFAULT '', owner TEXT NOT NULL DEFAULT '', due_date DATE, outcome TEXT NOT NULL DEFAULT '', residual_severity TEXT NOT NULL DEFAULT '', follow_up_date DATE, lessons_learned TEXT NOT NULL DEFAULT '', created_by TEXT NOT NULL DEFAULT '', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW())